package vn.hust.restaurant.repository;
import java.math.*;import java.sql.*;import java.time.*;import java.util.*;import vn.hust.restaurant.config.Database;import vn.hust.restaurant.model.*;
public class ReportRepository{
 public DashboardStats dashboard()throws SQLException{String s="""
 SELECT (SELECT ISNULL(SUM(TongThanhToan),0) FROM HoaDon WHERE TrangThaiThanhToan='DA_THANH_TOAN' AND CAST(NgayGioLap AS DATE)=CAST(GETDATE() AS DATE)),
 (SELECT COUNT(*) FROM HoaDon WHERE TrangThaiThanhToan='DA_THANH_TOAN' AND CAST(NgayGioLap AS DATE)=CAST(GETDATE() AS DATE)),
 (SELECT COUNT(*) FROM BanAn WHERE TrangThai IN('DANG_PHUC_VU','CHO_THANH_TOAN')),
 (SELECT COUNT(*) FROM ChiTietGoiMon WHERE TrangThaiCheBien IN('CHO_LAM','DANG_LAM')),
 (SELECT COUNT(*) FROM NguyenLieu WHERE SoLuongTon<=DinhMucToiThieu AND TrangThai='HOAT_DONG')
 """;try(Connection c=Database.getConnection();Statement st=c.createStatement();ResultSet r=st.executeQuery(s)){r.next();return new DashboardStats(r.getBigDecimal(1),r.getInt(2),r.getInt(3),r.getInt(4),r.getInt(5));}}
 public ReportTable revenue(LocalDate from,LocalDate to)throws SQLException{return query("Doanh thu theo ngày",List.of("Ngày","Số hóa đơn","Doanh thu","Giảm giá","Điểm giảm"),"SELECT CAST(NgayGioLap AS DATE),COUNT(*),SUM(TongThanhToan),SUM(TienGiamKhuyenMai),SUM(TienGiamDiem) FROM HoaDon WHERE TrangThaiThanhToan='DA_THANH_TOAN' AND CAST(NgayGioLap AS DATE) BETWEEN ? AND ? GROUP BY CAST(NgayGioLap AS DATE) ORDER BY 1",from,to);}
 public ReportTable topItems(LocalDate from,LocalDate to)throws SQLException{return query("Món bán chạy",List.of("Mã món","Tên món","Số lượng","Doanh thu"),"SELECT m.MaMonCode,m.TenMon,SUM(ct.SoLuong),SUM(ct.ThanhTien) FROM ChiTietHoaDon ct JOIN HoaDon h ON h.MaHoaDon=ct.MaHoaDon JOIN MonAn m ON m.MaMon=ct.MaMon WHERE h.TrangThaiThanhToan='DA_THANH_TOAN' AND CAST(h.NgayGioLap AS DATE) BETWEEN ? AND ? GROUP BY m.MaMonCode,m.TenMon ORDER BY SUM(ct.SoLuong) DESC",from,to);}
 public ReportTable lowStock()throws SQLException{List<List<Object>>rows=new ArrayList<>();String s="SELECT MaNLCode,TenNL,DonViTinh,SoLuongTon,DinhMucToiThieu FROM NguyenLieu WHERE SoLuongTon<=DinhMucToiThieu ORDER BY SoLuongTon";try(Connection c=Database.getConnection();Statement st=c.createStatement();ResultSet r=st.executeQuery(s)){while(r.next())rows.add(List.of(r.getObject(1),r.getObject(2),r.getObject(3),r.getObject(4),r.getObject(5)));}return new ReportTable("Nguyên liệu sắp hết",List.of("Mã","Tên","ĐVT","Tồn","Định mức"),rows);}
 public ReportTable stockReceipts(LocalDate from,LocalDate to)throws SQLException{return query("Nhập kho",List.of("Mã phiếu","Ngày nhập","Nhà cung cấp","Nhân viên","Tổng tiền"),"SELECT p.MaPhieuNhapCode,p.NgayNhap,ncc.TenNCC,nv.HoTen,p.TongTien FROM PhieuNhapKho p JOIN NhaCungCap ncc ON ncc.MaNCC=p.MaNCC JOIN NhanVien nv ON nv.MaNhanVien=p.MaNhanVien WHERE CAST(p.NgayNhap AS DATE) BETWEEN ? AND ? ORDER BY p.NgayNhap DESC",from,to);}
 private ReportTable query(String title,List<String>cols,String sql,LocalDate f,LocalDate t)throws SQLException{List<List<Object>>rows=new ArrayList<>();try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement(sql)){p.setDate(1,java.sql.Date.valueOf(f));p.setDate(2,java.sql.Date.valueOf(t));try(ResultSet r=p.executeQuery()){int n=r.getMetaData().getColumnCount();while(r.next()){List<Object>x=new ArrayList<>();for(int i=1;i<=n;i++)x.add(r.getObject(i));rows.add(x);}}}return new ReportTable(title,cols,rows);}
}
